public class StableSortDemoTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.util.List<Entry> entries(Object... pairs) {
        java.util.List<Entry> list = new java.util.ArrayList<>();
        for (int i = 0; i < pairs.length; i += 2) {
            list.add(new Entry((String) pairs[i], (Integer) pairs[i + 1]));
        }
        return list;
    }

    public static void main(String[] args) {
        check("example from the task", "[abe, cara, bob]",
                String.valueOf(StableSortDemo.namesGroupedStable(entries("cara", 2, "abe", 1, "bob", 2))));

        check("one group keeps insertion order (no name sorting!)", "[zed, amy, moe]",
                String.valueOf(StableSortDemo.namesGroupedStable(entries("zed", 1, "amy", 1, "moe", 1))));

        check("three groups", "[eve, gus, fay, dan]",
                String.valueOf(StableSortDemo.namesGroupedStable(entries("dan", 3, "eve", 1, "fay", 2, "gus", 1))));

        check("interleaved groups", "[amy, cal, bob, dee]",
                String.valueOf(StableSortDemo.namesGroupedStable(entries("bob", 2, "amy", 1, "dee", 2, "cal", 1))));

        check("negative group numbers", "[low, mid, high]",
                String.valueOf(StableSortDemo.namesGroupedStable(entries("mid", 0, "high", 5, "low", -2))));

        check("single entry", "[solo]",
                String.valueOf(StableSortDemo.namesGroupedStable(entries("solo", 9))));

        check("empty input", "[]",
                String.valueOf(StableSortDemo.namesGroupedStable(entries())));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

