record Entry(String name, int group) {}

public class StableSortDemo {

    public static java.util.List<String> namesGroupedStable(java.util.List<Entry> entries) {
        java.util.List<Entry> copy = new java.util.ArrayList<>(entries);
        copy.sort(java.util.Comparator.comparingInt(Entry::group));
        java.util.List<String> names = new java.util.ArrayList<>();
        for (Entry e : copy) {
            names.add(e.name());
        }
        return names;
    }
}
